SELECT
    JAN.ORGAO,
    JAN.COD_RUBRICA,
    JAN.RUBRICA,
    JAN.QUANTIDADE  QUANTIDADE_JAN,
    JAN.TOTAL_VALOR TOTAL_JAN,
    FEV.QUANTIDADE  QUANTIDADE_FEV,
    FEV.TOTAL_VALOR TOTAL_FEV,
    MAR.QUANTIDADE  QUANTIDADE_MAR,
    MAR.TOTAL_VALOR TOTAL_MAR,
    ABR.QUANTIDADE  QUANTIDADE_ABR,
    ABR.TOTAL_VALOR TOTAL_ABR,
    MAI.QUANTIDADE  QUANTIDADE_MAI,
    MAI.TOTAL_VALOR TOTAL_MAI,
    JUN.QUANTIDADE  QUANTIDADE_JUN,
    JUN.TOTAL_VALOR TOTAL_JUN
FROM
    (
    SELECT 
        'EMPRESA' ORGAO,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        COUNT(R.COD_RUBRICA) QUANTIDADE,
        SUM(FR.VALOR_CALCULADO) TOTAL_VALOR
    FROM
        SW_EMPRESA.FOLHA FO
        JOIN SW_EMPRESA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_EMPRESA.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    WHERE
        FO.MES = 1
        AND FO.ANO = 2026
        AND R.COD_RUBRICA IN (112992)
    GROUP BY
        'EMPRESA',
        R.COD_RUBRICA,
        R.NOME_RUBRICA
    ) JAN
    LEFT JOIN (
    SELECT
        'EMPRESA' ORGAO,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        COUNT(R.COD_RUBRICA) QUANTIDADE,
        SUM(FR.VALOR_CALCULADO) TOTAL_VALOR
    FROM
        SW_EMPRESA.FOLHA FO
        JOIN SW_EMPRESA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_EMPRESA.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    WHERE
        FO.MES = 2
        AND FO.ANO = 2026
        AND R.COD_RUBRICA IN (112992)
    GROUP BY
        'EMPRESA',
        R.COD_RUBRICA,
        R.NOME_RUBRICA
    ) FEV ON FEV.COD_RUBRICA = JAN.COD_RUBRICA
    LEFT JOIN (
    SELECT
        'EMPRESA' ORGAO,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
